        nums.push_back(stoi(temp));
    }
    return nums;
}

vector<char> replaceXWithChar(const vector<char>& array, int length, char replacement) {
    vector<char> result(length);
    for (int i = 0; i < length; i++) {
        result[i] = (array[i] == 'X') ? replacement : array[i];
    }
    return result;
}

long long process(const vector<char>& str, int n);

long long checkPattern(const vector<char>& str, const string& suffix, int n, int un) {
    if (n < 2) return 0;
    char lastChar = suffix[1];
